var a=[{title:`Ce înseamnă izolare`,text:`O flexie pentru biceps îndoaie mai ales cotul, iar o extensie pentru triceps îl îndreaptă. Ridicările laterale pun accent pe abducția umărului, extensiile de picior pe extensia genunchiului, iar flexiile de picior pe flexia genunchiului. Nicio mișcare reală nu activează un singur mușchi, așa că „izolare” înseamnă că acțiunea este concentrată pe o singură articulație, în timp ce alți mușchi tot ajută.`},{title:`Când este utilă`,text:`Izolarea poate adăuga muncă pentru un mușchi rămas în urmă, poate menține scăzută oboseala întregului corp sau îți poate oferi o opțiune simplă când echilibrul și coordonarea sunt dificile. Un ramat antrenează indirect bicepsul, de exemplu, dar flexiile oferă un stimul mai direct dacă creșterea brațelor este o prioritate. Aparatele pot face efortul țintit deosebit de ușor de controlat.`},{title:`Unde se potrivește într-o sesiune`,text:`Pentru forța generală, exercițiile compuse vin de obicei primele, cât ești proaspăt, iar izolarea urmează ca antrenament suplimentar. Dacă un mușchi izolat este obiectivul tău principal, este rezonabil să îl antrenezi devreme. Ordinea exercițiilor este o modalitate de a stabili priorități și o poți schimba când se schimbă prioritățile.`},{title:`Tehnică și progresie`,text:`Folosește o amplitudine comodă la articulația care lucrează, ține restul corpului stabil și nu balansa sarcina. Adaugă repetări sau puțină greutate doar când forma rămâne aceeași de la o repetare la alta. Sarcinile foarte mici funcționează când efortul este destul de mare, iar ridicarea unei cifre mai mari nu dovedește că antrenamentul este mai bun. Păstrează numărul total de serii la ce te poți reface. Dacă o mișcare provoacă durere, oprește-o; TrainUp nu oferă programe corective de recuperare.`}];var r=[{label:`Declarația de poziție ACSM 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`},{label:`Biblioteca de exerciții ACE`,url:`https://www.acefitness.org/resources/everyone/exercise-library/`},{label:`Mayo Clinic: tehnica antrenamentului cu greutăți (2026)`,url:`https://www.mayoclinic.org/healthy-lifestyle/fitness/in-depth/weight-training/art-20045842`}];var t={sections:a,sources:r};export{t as default,a as sections,r as sources};